import React, { useEffect, useMemo, useState } from 'react';
import './dashboard.css';
import { getNotifications, getProjects, getTasks } from './api';

const menuItems = ['Dashboard', 'Tasks', 'Projects', 'Analytics', 'Calendar', 'Team Members', 'Reports'];
const generalItems = ['Settings', 'Help & Support'];

function Dashboard({ user, userName = 'there', userRole = 'User', onLogout }) {
  const [activeTab, setActiveTab] = useState('Dashboard');
  const [tasks, setTasks] = useState([]);
  const [projects, setProjects] = useState([]);
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');

  useEffect(() => {
    let mounted = true;

    async function loadDashboard() {
      setLoading(true);
      setError('');

      try {
        const [taskResponse, projectResponse, notificationResponse] = await Promise.all([
          getTasks(),
          getProjects(),
          getNotifications(),
        ]);

        if (!mounted) return;
        setTasks(Array.isArray(taskResponse?.data) ? taskResponse.data : []);
        setProjects(Array.isArray(projectResponse?.data) ? projectResponse.data : []);
        setNotifications(Array.isArray(notificationResponse?.data) ? notificationResponse.data : []);
      } catch (err) {
        if (mounted) setError(err.message || 'Unable to load dashboard data.');
      } finally {
        if (mounted) setLoading(false);
      }
    }

    loadDashboard();
    return () => {
      mounted = false;
    };
  }, []);

  const dashboard = useMemo(() => {
    const totalTasks = tasks.length;
    const completed = tasks.filter(isCompleted).length;
    const inProgress = tasks.filter((task) => task.status === 'in-progress').length;
    const pending = Math.max(totalTasks - completed - inProgress, 0);
    const overdue = tasks.filter(isOverdue).length;
    const totalBudget = tasks.reduce((sum, task) => sum + Number(task.budget || 0), 0);
    const totalCost = tasks.reduce((sum, task) => sum + Number(task.cost || 0), 0);
    const utilization = totalBudget > 0 ? Math.round((totalCost / totalBudget) * 100) : Math.round((completed / (totalTasks || 1)) * 100);
    const averageDays = getAverageDaysToDue(tasks);
    const priority = {
      high: tasks.filter((task) => task.priority === 'high').length,
      medium: tasks.filter((task) => task.priority === 'medium').length,
      low: tasks.filter((task) => task.priority === 'low').length,
    };

    return {
      totalTasks,
      activeProjects: projects.length,
      completed,
      inProgress,
      pending,
      overdue,
      utilization: clamp(utilization, 0, 100),
      averageDays,
      priority,
    };
  }, [projects, tasks]);

  const statusCards = [
    { label: 'In Progress', value: dashboard.inProgress, color: 'orange' },
    { label: 'Completed', value: dashboard.completed, color: 'green' },
    { label: 'Overdue', value: dashboard.overdue, color: 'red' },
  ].map((item) => ({
    ...item,
    percent: percentOf(item.value, dashboard.totalTasks),
  }));

  const visibleTasks = useMemo(() => {
    const query = search.trim().toLowerCase();
    const filtered = query
      ? tasks.filter((task) => {
          const haystack = [
            task.title,
            task.description,
            task.priority,
            task.status,
            task.project?.name,
            task.assignedUser?.fullname,
            task.assignedUser?.username,
          ].filter(Boolean).join(' ').toLowerCase();
          return haystack.includes(query);
        })
      : tasks;

    return filtered;
  }, [search, tasks]);

  const workloadRows = buildWorkloadRows(tasks, userName).slice(0, 5);
  const unreadNotifications = notifications.filter((item) => !item.read).length;
  const firstName = String(userName || 'there').split(' ')[0];

  return (
    <div className="dashboard-page">
      <div className="dashboard-shell">
        <aside className="dashboard-sidebar">
          <div className="brand-card">
            <div className="brand-mark">T</div>
            <strong>TaskFlow</strong>
          </div>

          <nav className="side-nav" aria-label="Main navigation">
            <p>Menu</p>
            {menuItems.map((item) => (
              <button
                className={`nav-item ${activeTab === item ? 'active' : ''}`}
                type="button"
                key={item}
                onClick={() => setActiveTab(item)}
              >
                <span>{getMenuIcon(item)}</span>
                {item}
              </button>
            ))}
          </nav>

          <nav className="side-nav general-nav" aria-label="General navigation">
            <p>General</p>
            {generalItems.map((item) => (
              <button
                className={`nav-item ${activeTab === item ? 'active' : ''}`}
                type="button"
                key={item}
                onClick={() => setActiveTab(item)}
              >
                <span>{getMenuIcon(item)}</span>
                {item}
              </button>
            ))}
            <button className="nav-item" type="button" onClick={onLogout}>
              <span>O</span>
              Logout
            </button>
          </nav>

          <div className="upgrade-card">
            <strong>Upgrade to Pro</strong>
            <span>Unlock advanced analytics and manage unlimited projects.</span>
            <button type="button">Upgrade Now</button>
          </div>
        </aside>

        <main className="dashboard-main">
          <header className="dashboard-topbar">
            <div>
              <h1>Welcome back, {firstName}</h1>
              <p>Here is what is happening with your team today</p>
            </div>

            <label className="search-box">
              <span>S</span>
              <input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search here..."
                type="search"
              />
            </label>

            <button className="notification-button" type="button" aria-label="Notifications">
              N
              {unreadNotifications > 0 && <b>{unreadNotifications > 9 ? '9+' : unreadNotifications}</b>}
            </button>

            <div className="account-box">
              <div className="user-avatar">{getInitials(userName)}</div>
              <div>
                <strong>{userName}</strong>
                <small>{user?.email || userRole}</small>
              </div>
            </div>
          </header>

          {error && <div className="dashboard-alert">{error}</div>}

          {/* DASHBOARD TAB VIEW */}
          {activeTab === 'Dashboard' && (
            <>
              <section className="metric-grid">
                <MetricCard title="Active Projects" value={dashboard.activeProjects} helper="Projects in workspace" tone="sand" loading={loading} />
                <MetricCard title="Utilization Rate" value={`${dashboard.utilization}%`} helper="Budget or completion usage" tone="rose" loading={loading} />
                <MetricCard title="Average Time" value={`${dashboard.averageDays}`} suffix="Days" helper="Average days until due" tone="mint" loading={loading} />
                <MetricCard title="At Risk Projects" value={dashboard.overdue} helper="Tasks currently overdue" tone="blush" loading={loading} />
              </section>

              <div className="dashboard-grid">
                <section className="panel status-panel">
                  <PanelHeader title="Task Status Distribution" />
                  <div className="status-bars">
                    {statusCards.map((item) => (
                      <div className={`status-card ${item.color}`} key={item.label}>
                        <span>{item.label}</span>
                        <strong>{item.percent}%</strong>
                        <div><i style={{ width: `${item.percent}%` }} /></div>
                      </div>
                    ))}
                  </div>
                </section>

                <section className="panel priority-panel">
                  <PanelHeader title="Task Priority" helper="Distribution by priority level" />
                  <PriorityDonut priority={dashboard.priority} total={dashboard.totalTasks} />
                </section>
              </div>

              <div className="dashboard-grid bottom-grid">
                <section className="panel activity-panel">
                  <PanelHeader title="Team Activity" helper="Understand productivity and workload." />
                  <div className="activity-summary">
                    <strong>{percentOf(dashboard.completed, dashboard.totalTasks)}%</strong>
                    <span>completion rate</span>
                  </div>
                  <ActivityHeatmap tasks={tasks} />
                </section>

                <section className="panel workload-panel">
                  <PanelHeader title="Team Workload" action="See All" />
                  <div className="workload-table">
                    <div className="workload-head">
                      <span>Name</span>
                      <span>Active work</span>
                      <span>Overdue</span>
                      <span>Status</span>
                    </div>

                    {loading ? (
                      <LoadingRows />
                    ) : workloadRows.length ? workloadRows.map((row) => (
                      <div className="workload-row" key={row.name}>
                        <div className="person-cell">
                          <div className="person-avatar">{getInitials(row.name)}</div>
                          <div>
                            <strong>{row.name}</strong>
                            <small>{row.role}</small>
                          </div>
                        </div>
                        <span>{row.active}</span>
                        <span>{row.overdue}</span>
                        <span className={`workload-status ${row.tone}`}>{row.status}</span>
                      </div>
                    )) : (
                      <div className="empty-state">No workload data yet.</div>
                    )}
                  </div>
                </section>
              </div>

              <section className="panel task-panel">
                <PanelHeader title="Recent Tasks" helper="Live from your backend task list" />
                <div className="task-list">
                  {loading ? (
                    <LoadingRows />
                  ) : visibleTasks.length ? visibleTasks.slice(0, 6).map((task) => (
                    <TaskRow task={task} key={task._id || task.id || task.title} />
                  )) : (
                    <div className="empty-state">{search ? 'No tasks match your search.' : 'No tasks found yet.'}</div>
                  )}
                </div>
              </section>
            </>
          )}

          {/* TASKS TAB VIEW */}
          {activeTab === 'Tasks' && (
            <section className="panel task-panel">
              <PanelHeader title="All Tasks" helper={`Showing ${visibleTasks.length} total tasks`} />
              <div className="task-list">
                {loading ? (
                  <LoadingRows />
                ) : visibleTasks.length ? visibleTasks.map((task) => (
                  <TaskRow task={task} key={task._id || task.id || task.title} />
                )) : (
                  <div className="empty-state">{search ? 'No tasks match your search.' : 'No tasks found yet.'}</div>
                )}
              </div>
            </section>
          )}

          {/* PROJECTS TAB VIEW */}
          {activeTab === 'Projects' && (
            <section className="panel">
              <PanelHeader title="Projects" helper="Active workspace projects" />
              <div className="task-list">
                {loading ? (
                  <LoadingRows />
                ) : projects.length ? projects.map((project) => (
                  <div className="task-row" key={project._id || project.id || project.name}>
                    <div className="task-dot" />
                    <div>
                      <strong>{project.name || 'Untitled Project'}</strong>
                      <small>{project.description || 'No description available'}</small>
                    </div>
                    <span>{project.category || 'General'}</span>
                    <span className="task-badge completed">{project.status || 'Active'}</span>
                  </div>
                )) : (
                  <div className="empty-state">No projects found.</div>
                )}
              </div>
            </section>
          )}

          {/* OTHER TAB VIEWS */}
          {activeTab !== 'Dashboard' && activeTab !== 'Tasks' && activeTab !== 'Projects' && (
            <section className="panel">
              <PanelHeader title={activeTab} helper={`Manage your ${activeTab.toLowerCase()} settings and preferences`} />
              <div className="empty-state">
                The <strong>{activeTab}</strong> section is currently ready for content integration.
              </div>
            </section>
          )}
        </main>
      </div>
    </div>
  );
}

function MetricCard({ title, value, helper, suffix = '', tone, loading }) {
  return (
    <article className={`metric-card ${tone}`}>
      <span>{title}</span>
      <strong>{loading ? '--' : value}<small>{loading ? '' : suffix}</small></strong>
      <p>{helper}</p>
    </article>
  );
}

function PanelHeader({ title, helper, action }) {
  return (
    <div className="panel-heading">
      <div>
        <h2>{title}</h2>
        {helper && <p>{helper}</p>}
      </div>
      <button className="more-button" type="button">{action || '...'}</button>
    </div>
  );
}

function PriorityDonut({ priority, total }) {
  const high = percentOf(priority.high, total);
  const medium = percentOf(priority.medium, total);
  const low = Math.max(0, 100 - high - medium);

  return (
    <>
      <div
        className="priority-donut"
        style={{
          '--high': `${high}%`,
          '--medium': `${high + medium}%`,
        }}
      >
        <span />
      </div>
      <div className="priority-legend">
        <span><i className="high" />High Priority: {priority.high}</span>
        <span><i className="medium" />Medium Priority: {priority.medium}</span>
        <span><i className="low" />Low Priority: {priority.low || Math.round((low / 100) * total)}</span>
      </div>
    </>
  );
}

function ActivityHeatmap({ tasks }) {
  const days = ['Sat', 'Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri'];
  const times = ['10:00', '09:30', '09:00', '08:30', '08:00'];
  const densitySeed = Math.max(tasks.length, 1);

  return (
    <div className="heatmap">
      <div />
      {days.map((day) => <span key={day}>{day}</span>)}
      {times.map((time, row) => (
        <React.Fragment key={time}>
          <span>{time}</span>
          {days.map((day, col) => {
            const level = ((row + 1) * (col + 2) + densitySeed) % 4;
            return <i className={`level-${level}`} key={`${day}-${time}`} />;
          })}
        </React.Fragment>
      ))}
    </div>
  );
}

function TaskRow({ task }) {
  return (
    <div className="task-row">
      <div className={`task-dot ${task.priority || 'medium'}`} />
      <div>
        <strong>{task.title || 'Untitled task'}</strong>
        <small>{task.project?.name || task.taskType || 'General task'}</small>
      </div>
      <span>{formatDate(task.dueDate)}</span>
      <span className={`task-badge ${task.status || 'pending'}`}>{formatStatus(task.status)}</span>
    </div>
  );
}

function LoadingRows() {
  return (
    <>
      {[1, 2, 3].map((item) => <div className="loading-row" key={item} />)}
    </>
  );
}

function buildWorkloadRows(tasks, fallbackName) {
  const grouped = new Map();

  tasks.forEach((task) => {
    const person = task.assignedUser || task.creator || {};
    const name = person.fullname || person.username || fallbackName || 'Team Member';
    const current = grouped.get(name) || {
      name,
      role: person.role || 'Team Member',
      active: 0,
      overdue: 0,
    };

    if (!isCompleted(task)) current.active += 1;
    if (isOverdue(task)) current.overdue += 1;
    grouped.set(name, current);
  });

  return Array.from(grouped.values()).map((row) => {
    if (row.overdue >= 3) return { ...row, status: 'Overloaded', tone: 'danger' };
    if (row.overdue > 0) return { ...row, status: 'On Track', tone: 'warning' };
    if (row.active >= 6) return { ...row, status: 'Under Pressure', tone: 'busy' };
    return { ...row, status: 'Balanced', tone: 'good' };
  });
}

function isCompleted(task) {
  return Boolean(task.completed || task.status === 'completed');
}

function isOverdue(task) {
  if (!task.dueDate || isCompleted(task)) return false;
  const dueDate = new Date(task.dueDate);
  if (Number.isNaN(dueDate.getTime())) return false;
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  dueDate.setHours(0, 0, 0, 0);
  return dueDate < today;
}

function getAverageDaysToDue(tasks) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const dayCounts = tasks
    .filter((task) => task.dueDate && !isCompleted(task))
    .map((task) => Math.max(0, Math.ceil((new Date(task.dueDate) - today) / 86400000)))
    .filter((value) => Number.isFinite(value));

  if (!dayCounts.length) return 0;
  return (dayCounts.reduce((sum, value) => sum + value, 0) / dayCounts.length).toFixed(1);
}

function percentOf(value, total) {
  return total ? Math.round((value / total) * 100) : 0;
}

function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}

function formatDate(date) {
  if (!date) return 'No due date';
  const value = new Date(date);
  if (Number.isNaN(value.getTime())) return 'No due date';
  return value.toLocaleDateString('en-IN', { day: '2-digit', month: 'short' });
}

function formatStatus(status = 'pending') {
  if (status === 'in-progress') return 'In Progress';
  return status.charAt(0).toUpperCase() + status.slice(1);
}

function getInitials(name) {
  return String(name || 'U')
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase();
}

function getMenuIcon(item) {
  const icons = {
    Dashboard: 'D',
    Tasks: 'T',
    Projects: 'P',
    Analytics: 'A',
    Calendar: 'C',
    'Team Members': 'M',
    Reports: 'R',
    Settings: 'S',
    'Help & Support': '?',
  };
  return icons[item] || item.charAt(0);
}

